                C('Futur: il ___ (mourir)', 'he will die', ['mourra', 'mourira', 'moura', 'meurera'], 'mourra', 'An -rr- stem.', 'il <b>mourra</b>.'),
                C('Participe passé masculin de devoir: ___', 'had to (masc.)', ['dû', 'du', 'dut', 'dûe'], 'dû', 'A circumflex: not du (de + le).', '<b>dû</b>.'),
                C('Futur: je ___ (voir)', 'I will see', ['verrai', 'voirai', 'verai', 'voierai'], 'verrai', 'An -rr- stem.', 'je <b>verrai</b>.'),
