                    dict(label="Le fait qu'il est parti prouve tout.", en=['The fact that he left proves everything. (a fact)', 'That he left surprises me. (a judgement)'], a=T(('s', "Le fait qu'il", ''), ('v', 'est parti', 'x'), ('o', 'prouve tout.', '')), b=T(('s', "Le fait qu'il", ''), ('v', 'soit parti', 'x'), ('o', "m'étonne.", ''))),
